  width: 320px;
  background-color: #f2f2f2;
  padding: 10px;
}

.card {
  box-sizing: border-box;
  width: 100%;
  padding: 16px;
  border: 1px solid #cccccc;
  border-radius: 4px;
  background-color: #ffffff;
  margin-bottom: 12px;
}

.card h3 {
  margin: 0 0 8px 0;
  color: #111111;
}

.card p {
  margin: 0;
  color: #555555;
  line-height: 1.4;
}

