/* TODO: .profile-card - box-sizing border-box, width 280px, padding 24px, border 1px solid #e0e0e0, border-radius 12px, background-color #ffffff, text-align center, margin 0 auto */

/* TODO: .avatar-wrap - position relative, width 80px, height 80px, margin 0 auto 16px */

/* TODO: .avatar - width 100%, height 100%, border-radius 50%, object-fit cover, display block */

/* TODO: .status-dot - position absolute, bottom 2px, right 2px, width 14px, height 14px, background-color #2ecc71, border 2px solid #ffffff, border-radius 50% */

/* TODO: .name - margin 0 0 4px 0, font-size 1.25rem, color #111111 */

/* TODO: .title - margin 0 0 12px 0, font-size 0.875rem, color #767676, text-transform uppercase, letter-spacing 0.03em */

/* TODO: .bio - margin 0 0 20px 0, font-size 0.9375rem, color #444444, line-height 1.5 */

/* TODO: .follow-btn - box-sizing border-box, padding 10px 24px, border none, border-radius 6px, background-color #111111, color #ffffff, font-weight 600, cursor pointer; plus a :hover state that only changes background-color to #333333 */

solutionCodeJson.code:
.profile-card {
  box-sizing: border-box;
  width: 280px;
  padding: 24px;
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  background-color: #ffffff;
  text-align: center;
  margin: 0 auto;
}

.avatar-wrap {
  position: relative;
  width: 80px;
  height: 80px;
  margin: 0 auto 16px;
}

.avatar {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  display: block;
}

.status-dot {
  position: absolute;
  bottom: 2px;
  right: 2px;
  width: 14px;
  height: 14px;
  background-color: #2ecc71;
  border: 2px solid #ffffff;
  border-radius: 50%;
}

.name {
  margin: 0 0 4px 0;
  font-size: 1.25rem;
  color: #111111;
}

.title {
  margin: 0 0 12px 0;
  font-size: 0.875rem;
  color: #767676;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.bio {
  margin: 0 0 20px 0;
  font-size: 0.9375rem;
  color: #444444;
  line-height: 1.5;
}

.follow-btn {
  box-sizing: border-box;
  padding: 10px 24px;
  border: none;
  border-radius: 6px;
  background-color: #111111;
  color: #ffffff;
  font-weight: 600;
  cursor: pointer;
}

.follow-btn:hover {
  background-color: #333333;
}
